<script setup>
import BusyFeedback from './BusyFeedback.vue';
import {ref,onMounted,onUnmounted,computed} from 'vue';import {api,loadCatalog,invalidateCatalog} from './api';
const courses=ref([]),meta=ref({exams:[],terms:[]}),form=ref({course_id:'',exam_type_id:'',term_id:'',name:''}),file=ref(null),job=ref(null),paper=ref(null),busy=ref(false),retrying=ref(false),error=ref(''),catalogLoading=ref(true);let poll;
const status=computed(()=>job.value?.effective_status||job.value?.status||'');
const failed=computed(()=>['EXTRACTION_FAILED','PROCESSING_FAILED'].includes(status.value));
const done=computed(()=>['AVAILABLE','PARTIAL'].includes(status.value));
const stage=computed(()=>busy.value?'Uploading…':failed.value?'Extraction Failed ✗':done.value?'Completed ✓':status.value==='QUEUED'?'Waiting for processing worker…':job.value?.events?.at(-1)?.stage==='VALIDATING'?'Validating…':job.value?.events?.at(-1)?.stage==='DETECTING_ANSWERS'?'Detecting answers…':status.value==='PROCESSING'?'Processing PDF / extracting questions…':'');
async function refreshCatalog(){catalogLoading.value=true;error.value='';try{const catalog=await loadCatalog();courses.value=catalog.courses;meta.value=catalog.meta}catch(e){error.value=e.message}finally{catalogLoading.value=false}}
onMounted(refreshCatalog);
defineExpose({refreshCatalog});
onUnmounted(()=>clearInterval(poll));
async function refresh(){try{const d=await api('/admin/ingestion/'+job.value.id);job.value=d.file;paper.value=d.paper;if(done.value||failed.value)clearInterval(poll)}catch(e){error.value=e.message}}
function watchJob(){clearInterval(poll);poll=setInterval(refresh,1500);refresh()}
async function upload(){if(busy.value)return;busy.value=true;error.value='';try{if(!file.value)throw Error('Select a PDF.');const data=new FormData();Object.entries(form.value).forEach(([k,v])=>data.append(k,v));data.append('file',file.value);const d=await api('/admin/upload-pyq',{method:'POST',form:data});job.value=d.file;paper.value=d.paper;invalidateCatalog();watchJob()}catch(e){error.value=e.message}finally{busy.value=false}}
async function retry(){if(retrying.value)return;retrying.value=true;error.value='';try{await api('/admin/ingestion/'+job.value.id+'/retry',{method:'POST'});watchJob()}catch(e){error.value=e.message}finally{retrying.value=false}}
</script>
<template><section class="panel"><h2>Upload PYQ PDF</h2><p class="muted">Choose the paper metadata and upload. Processing and student availability are automatic.</p><p v-if="error" class="alert alert-danger" role="alert">{{error}}</p><div v-if="catalogLoading" class="request-feedback"><BusyFeedback label="Loading catalog…"/></div><button v-else-if="!courses.length" type="button" class="btn btn-light" @click="refreshCatalog">Retry catalog</button><form @submit.prevent="upload"><div class="form-grid"><label>Course<select class="form-select" v-model="form.course_id" required aria-label="Upload course"><option value="">Select Course</option><option v-for="c in courses" :value="c.id">{{c.name}}</option></select></label><label>Exam type<select class="form-select" v-model="form.exam_type_id" required aria-label="Upload exam type"><option value="">Select Exam Type</option><option v-for="e in meta.exams" :value="e.id">{{e.name}}</option></select></label><label>Term / Year<select class="form-select" v-model="form.term_id" required aria-label="Upload term"><option value="">Select Term</option><option v-for="t in meta.terms" :value="t.id">{{t.name}}</option></select></label><label>Paper title (optional)<input class="form-control" v-model="form.name" placeholder="Uses the PDF filename when blank"></label></div><label class="d-block my-3">PDF file<input class="form-control" type="file" accept="application/pdf" required @change="file=$event.target.files[0]" aria-label="Upload PDF file"></label><button class="btn btn-primary" :disabled="busy||catalogLoading||!courses.length||job&&!done&&!failed"><BusyFeedback v-if="busy" label="Uploading…"/><template v-else>Upload PDF</template></button></form><section v-if="job" class="mt-4" aria-live="polite"><h3><BusyFeedback v-if="!done&&!failed" :label="stage"/><template v-else>{{stage}}</template></h3><p v-if="status==='QUEUED'" class="muted">Processing starts when the background worker picks up this upload.</p><p v-if="done">{{paper?.question_count}} questions are ready. {{status==='PARTIAL'?'Some records were incomplete; reliable questions are available.':''}}</p><p v-if="job.error" class="alert alert-danger">{{job.error}}</p><a v-if="done" :href="'#/paper/'+paper.id" class="btn btn-primary">Open paper →</a><button v-if="failed" @click="retry" :disabled="retrying" class="btn btn-outline-primary"><BusyFeedback v-if="retrying" label="Queuing retry…"/><template v-else>Retry</template></button><details class="mt-3"><summary>Processing log</summary><ol><li v-for="e in job.events">{{e.stage}} — {{e.message}}</li></ol></details></section></section></template>
